"""X-THM-03 insulation schedule (AQS-THM-003). Every piped line (AQS-ISO-002 quantities) and every designed vessel (params.design T_C) gets an
insulation duty from its temperature: hot (> ins_hot_threshold_C) personnel protection to a ins_hot_surface_max_C surface [ASTM_C1055], cold
(below the ambient dew point [ASHRAE_FUND2021_PSY]) anti-condensation to dew point + 1 K. Thickness = smallest standard thickness meeting the
surface limit by radial conduction in series with the outer coefficient [ASTM_C680]. Mineral wool [ASTM_C547] hot, elastomeric [ASTM_C534] cold.
Inputs A-M-158. Writes docs-authority/INSULATION_SCHEDULE.md and docs-authority/insulation_schedule.csv. Run: python3 docs-authority/_insulation.py"""
import csv, json, math, os, sys
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, R)
from flow_graph.param import drivers as DR
d = DR.load(); v = lambda k: DR.val(d, k)
H, TS, TA, RH, KA, KB, KE, TH = (v(k) for k in ('ins_h_surface_W_m2K', 'ins_hot_surface_max_C', 'ins_ambient_C', 'ins_RH', 'ins_k_mw_a', 'ins_k_mw_b', 'ins_k_elast', 'ins_hot_threshold_C'))
a, b = 17.62, 243.12; gam = math.log(RH) + a*TA/(b + TA); TDEW = b*gam/(a - gam)       # Magnus form (ASHRAE_FUND2021_PSY)
LOSS_FRAC = v('ins_loss_frac_of_duty')
THK = (13, 25, 38, 50, 65, 75, 100, 125, 150, 200)
OD = {15: 21.3, 20: 26.7, 25: 33.4, 32: 42.2, 40: 48.3, 50: 60.3, 65: 73.0, 80: 88.9, 100: 114.3, 150: 168.3, 200: 219.1, 250: 273.0, 300: 323.8}
def surf(T, r1, t, k):
    r2 = r1 + t/1000; Rins = math.log(r2/r1)/(2*math.pi*k); Rs = 1/(2*math.pi*r2*H); q = (T - TA)/(Rins + Rs); return TA + q*Rs, q
def pick(T, r1, qmax=None):
    hot = T > TH
    for t in THK:
        k = KA + KB*(T + TS)/2 if hot else KE
        Ts, q = surf(T, r1, t, k)
        if ((hot and Ts <= TS) or (not hot and Ts >= TDEW + 1)) and (qmax is None or q <= qmax): return t, Ts, q, k, True
    return THK[-1], Ts, q, k, qmax is None
def main():
    g = json.load(open(os.path.join(R, 'flow_graph/plant_flow_graph.json'))); E = {e['stream_id']: e for e in g['edges']}
    P2 = {'P2': 85.0}
    rows = []
    for r in csv.DictReader(open(os.path.join(R, 'docs-authority/iso/ISO_SHEETS.csv'))):
        e = E.get(r['line']); p = (e or {}).get('params') or {}
        T = p.get('T_C') if isinstance(p.get('T_C'), (int, float)) else max(p.get('supply_C', -999), p.get('return_C', -999)) if 'supply_C' in p else P2.get(r['cls'] if 'cls' in r else r.get('class'), None)
        if T is None or T == -999 or TDEW + 1 <= T <= TH: continue
        dn = int(float(r['DN'])); r1 = OD.get(dn, dn*1.1)/2000; L = float(r['pipe_m'] or 0)
        duty = p.get('duty_rated_kw'); qmax = LOSS_FRAC*duty*1000/L if duty and L else None   # heat-conservation limit on heat-ladder lines
        t, Ts, q, k, ok = pick(T, r1, qmax)
        rows.append(dict(item=r['line'], kind='line', DN=dn, T_C=T, duty='hot, personnel protection' if T > TH else 'cold, anti-condensation',
                         material='mineral wool (ASTM C547), Al jacket' if T > TH else 'flexible elastomeric (ASTM C534), vapour-sealed', thk_mm=t, surface_C=round(Ts, 1),
                         k=round(k, 4), loss_W_m=round(q, 2), length_m=L, loss_W=round(q*L, 1), loss_frac_of_duty=round(q*L/(duty*1000), 3) if duty else '', meets_limit=ok, insulation_m3=round(math.pi*((r1 + t/1000)**2 - r1**2)*L, 4)))
    for n in g['nodes']:
        ds = (n.get('params') or {}).get('design') or {}; T = ds.get('T_C')
        if not isinstance(T, (int, float)) or TDEW + 1 <= T <= TH: continue
        D = ds.get('D_mm') or ds.get('OD_mm'); Hh = ds.get('H_mm')
        if not (D and Hh): continue
        r1 = D/2000; t, Ts, q, k, _ = pick(T, r1); Lv = Hh/1000
        rows.append(dict(item=n['unit_id'], kind='vessel', DN=D, T_C=T, duty='hot, personnel protection and heat conservation', material='mineral wool (ASTM C547), SS cladding',
                         thk_mm=t, surface_C=round(Ts, 1), k=round(k, 4), loss_W_m=round(q, 2), length_m=Lv, loss_W=round(q*Lv*1.3, 1), loss_frac_of_duty='', meets_limit=True,
                         insulation_m3=round(math.pi*((r1 + t/1000)**2 - r1**2)*Lv*1.3, 4)))
    with open(os.path.join(R, 'docs-authority/insulation_schedule.csv'), 'w', newline='') as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
    hot = [x for x in rows if x['T_C'] > TH]; cold = [x for x in rows if x['T_C'] <= TH]
    md = ['# Insulation schedule', '', 'Document number: AQS-THM-003', 'Revision: A', 'Date: 2026-10-15',
          'Authority: AQS-PLAN-007 X-THM-03. Generated by `docs-authority/_insulation.py` from the graph and AQS-ISO-002. Study. Inputs A-M-158.', '',
          f'Method: radial conduction in series with an outer coefficient of {H} W/(m2 K) (ASTM_C680). Hot items above {TH} C: smallest standard thickness giving a surface at or below {TS} C (ASTM_C1055 contact threshold about 60 C). Cold items: surface at least 1 K above the dew point {TDEW:.1f} C of {TA} C / {RH*100:.0f} % RH air (ASHRAE_FUND2021_PSY). Vessel losses include 30 % for heads and nozzles.', '',
          f'{len(hot)} hot items, {len(cold)} cold items. Total insulation {sum(x["insulation_m3"] for x in rows):.3f} m3; total loss {sum(x["loss_W"] for x in hot)/1000:.3f} kW hot, {sum(x["loss_W"] for x in cold):.1f} W gain cold.', '',
          f"Heat-ladder lines (HL-*) also carry a heat-conservation limit: loss at most {LOSS_FRAC*100:.0f} % of the rated loop duty. {sum(1 for x in rows if not x['meets_limit'])} lines cannot meet it even at {THK[-1]} mm: their loss fraction is listed and carried to X-THM-01 (heat ladder duty balance).", '',
          '| Item | Kind | DN/D mm | T C | Duty | Material | Thickness mm | Surface C | Loss W/m | Length m | Loss W | Loss / duty |', '|---|---|---|---|---|---|---|---|---|---|---|---|']
    md += [f"| {x['item']} | {x['kind']} | {x['DN']} | {x['T_C']} | {x['duty']} | {x['material']} | {x['thk_mm']} | {x['surface_C']} | {x['loss_W_m']} | {x['length_m']} | {x['loss_W']} | {x['loss_frac_of_duty']}{'' if x['meets_limit'] else ' (limit not met)'} |" for x in sorted(rows, key=lambda x: -x['T_C'])]
    # X-THM-04 (A-M-165): heat-ladder line losses on the graph. A line in flow loses q x L continuously; a normally-off tie (duty_normal 0)
    # is stagnant in normal operation and loses only while it runs (single-ladder case). Each HL line gets its loss in params and the rated
    # duty its source must cover (rated + loss); the normal loss goes to HEAT_SINK on a thermal edge HLL-<line> from the source unit.
    hl = [x for x in rows if x['item'].startswith('HL-') and x['kind'] == 'line']; N = {n['unit_id'] for n in g['nodes']}
    g['edges'] = [e for e in g['edges'] if not e['stream_id'].startswith('HLL-')]
    tot_n = tot_r = 0.0
    for x in hl:
        e = E[x['item']]; p = e['params']; on = (p.get('duty_normal_kw') or 0) > 0
        p['line_loss_W'] = x['loss_W']; p['line_loss_normal_W'] = x['loss_W'] if on else 0.0
        p['duty_source_rated_kw'] = round(p['duty_rated_kw'] + x['loss_W']/1000, 4); p['line_loss_basis'] = 'X-THM-04 (AQS-THM-003, A-M-165)'
        tot_r += x['loss_W']; tot_n += p['line_loss_normal_W']
        if on and 'HEAT_SINK' in N:
            g['edges'].append({'stream_id': 'HLL-' + x['item'][3:], 'from_unit_id': e['from_unit_id'], 'to_unit_id': 'HEAT_SINK', 'phase': 'E', 'layers': ['thermal'], 'presence': 'present',
                               'carries': f"insulated line loss of {x['item']} to the hall air", 'header': 'tray', 'forbidden': 'HDR_O2, HDR_CO2', 'claim_status': 'Claimed / Partial',
                               'rate': {'value': round(x['loss_W']/1000, 4), 'unit': 'kW', 'status': 'study', 'note': f"X-THM-04: {x['loss_W_m']} W/m x {x['length_m']} m at {x['thk_mm']} mm (AQS-THM-003, A-M-165)."},
                               'from_sector_id': e.get('from_sector_id'), 'to_sector_id': None, 'open_boundary': False, 'namespace': 'S', 'gap_flags': [], 'notes': None})
    # X-THM-01 (A-M-166): re-close each store on the graph rates. The store that feeds a lossy line is short by the loss; the shortfall
    # passes down the ladder as less heat on the downhill step (Q1 -> Q2 -> Q3 -> Q4 -> Q4_BUS) and ends as less heat rejected on HL-Q4-REJ.
    E2 = {e['stream_id']: e for e in g['edges']}
    def base(sid):
        r = E2[sid]['rate']; pp = E2[sid].setdefault('params', {}) or {}
        if E2[sid].get('params') is None: E2[sid]['params'] = pp
        if ' | X-THM-01' not in (r.get('note') or '') or 'rate_before_line_loss_kw' not in pp: pp['rate_before_line_loss_kw'] = r['value']   # upstream rewrote the rate
        return pp['rate_before_line_loss_kw']
    hll = lambda u: sum(e['rate']['value'] for e in g['edges'] if e['stream_id'].startswith('HLL-') and e['from_unit_id'] == u)
    ladder = {}
    for L in ('A', 'B'):
        dsum = 0.0
        for q, sid in ((f'Q1_{L}', f'HL-Q1-{L}-DOWN'), (f'Q2_{L}', f'HL-Q2-{L}-DOWN'), (f'Q3_{L}', f'HL-Q3-{L}-DOWN'), (f'Q4_{L}', f'HL-Q4-{L}-BUS')):
            dsum += hll(q); b0 = base(sid); E2[sid]['rate']['value'] = round(b0 - dsum, 4)
            assert E2[sid]['rate']['value'] >= 0, (sid, b0, dsum)
            E2[sid]['rate']['note'] = E2[sid]['rate']['note'].split(' | X-THM-01')[0] + f' | X-THM-01: {b0} kW less {dsum:.4f} kW of insulated line loss upstream (A-M-166).'
            ladder[q] = dsum
    import collections
    def tbal():
        bb = collections.Counter()
        for e in g['edges']:
            if 'thermal' in e['layers'] and e.get('presence') != 'retired' and e['rate'].get('unit') == 'kW':
                bb[e['from_unit_id']] -= float(e['rate']['value'] or 0); bb[e['to_unit_id']] += float(e['rate']['value'] or 0)
        return bb
    b0 = base('HL-Q4-REJ'); r0 = E2['HL-Q4-REJ']['rate']['value']; E2['HL-Q4-REJ']['rate']['value'] = round(r0 + tbal()['Q4_BUS'] - 0.001, 4)   # Q4_BUS closes on the rejection
    dl = b0 - E2['HL-Q4-REJ']['rate']['value']
    E2['HL-Q4-REJ']['rate']['note'] = E2['HL-Q4-REJ']['rate']['note'].split(' | X-THM-01')[0] + f' | X-THM-01: closes Q4_BUS after the line losses carried down the ladder (A-M-166).'
    import collections
    bal = collections.Counter()
    for e in g['edges']:
        if 'thermal' in e['layers'] and e.get('presence') != 'retired' and e['rate'].get('unit') == 'kW':
            bal[e['from_unit_id']] -= float(e['rate']['value'] or 0); bal[e['to_unit_id']] += float(e['rate']['value'] or 0)
    stores = [u for u in sorted(bal) if u[:3] in ('Q1_', 'Q2_', 'Q3_', 'Q4_')]
    assert all(abs(bal[u]) < 0.01 for u in stores), {u: bal[u] for u in stores}
    md += ['', '## Heat-ladder store closure (X-THM-01, A-M-166)', '', '| Store | Line loss carried down, kW | Residual on graph rates, kW |', '|---|---|---|']
    md += [f'| {u} | {ladder.get(u, 0.0):.4f} | {bal[u]:.4f} |' for u in stores]
    md += ['', f"Each store closes on the graph rates (in = out within 0.01 kW). Line losses pass down the ladder as less heat on the downhill steps and end as {ladder['Q4_A'] + ladder['Q4_B']:.3f} kW less rejected on HL-Q4-REJ, which closes Q4_BUS at {E2['HL-Q4-REJ']['rate']['value']} kW. No electric trim is added: Q4 rejects a surplus in normal operation."]
    if '--graph' in sys.argv: open(os.path.join(R, 'flow_graph/plant_flow_graph.json'), 'w').write(json.dumps(g, indent=2))
    md += ['', '## Heat-ladder line losses (X-THM-04, A-M-165)', '',
           f"All {len(hl)} heat-ladder lines carry their loss on the graph: params line_loss_W, and duty_source_rated_kw = rated duty + loss, which the source of each loop must deliver. Lines in flow in normal operation put their loss on a thermal edge HLL-<line> to HEAT_SINK ({tot_n/1000:.3f} kW total). The normally-off same-tier ties (HL-Q*-X, duty_normal 0) are stagnant in normal operation and cool down; they lose heat only while running in the single-ladder case, when their {sum(x['loss_W'] for x in hl if not ((E[x['item']]['params'].get('duty_normal_kw') or 0) > 0)):.0f} W is covered by the rated source duty. Total if every line ran: {tot_r/1000:.3f} kW.",
           '', "Why the 10 % target is not met on 12 lines, and why that is accepted: the loops are 0.3-2 kW at 95-250 C on DN15-25 over 12-29 m; above about 150 C mineral wool at 200 mm still loses 14-29 W/m (k rises with temperature, ASTM_C547), so the fraction is set by the small duty, not by the insulation. Moving the batteries next to their sources would trade these runs for the same length on the user side, since each store serves several users across the hall (AQS-HEAT-LADDER-001). The absolute loss is small against the 146.5 kW HEAT_SINK and is now carried in the ladder duties; the loop sources are checked against duty_source_rated_kw under X-THM-01."]
    open(os.path.join(R, 'docs-authority/INSULATION_SCHEDULE.md'), 'w').write('\n'.join(md) + '\n')
    print(len(rows), 'items', len(hot), 'hot', len(cold), 'cold', round(TDEW, 1))
if __name__ == '__main__': main()
